<script setup lang="ts">
import SoftSelect from '../components/SoftSelect.vue'
import { ref,watch } from 'vue'
import { useRoute } from 'vue-router'
import { api, post, query } from '../lib/api'
import { isParent, selectedDate } from '../lib/state'
import { useResource, loadStudents, openDialog, studentOptions, subjectOptions, label, type Field } from '../lib/ui'
import type { Homework } from '../lib/types'
import PageHeader from '../components/PageHeader.vue'
import AppIcon from '../components/AppIcon.vue'
import LoadState from '../components/LoadState.vue'
import StatusBadge from '../components/StatusBadge.vue'
import AttachmentList from '../components/AttachmentList.vue'
const route=useRoute();const studentId=ref<string | number>(String(route.query.studentId||''));const subject=ref('');const status=ref(String(route.query.status||''));const detail=ref<Homework|null>(null)
const students=useResource(loadStudents)
const {data,loading,error,refresh}=useResource(()=>api<Homework[]>(`/homework${query({date:selectedDate.value,studentId:studentId.value,subject:subject.value,status:status.value})}`),[selectedDate,studentId,subject,status])
let openedRequested=false
watch(data,rows=>{if(openedRequested||!route.query.homeworkId)return;const row=rows?.find(h=>h.id===Number(route.query.homeworkId));if(row){openedRequested=true;detail.value=row}})
const statuses=['NOT_STARTED','IN_PROGRESS','PENDING_REVIEW','CORRECTION','PENDING_RECHECK','COMPLETED']
async function create() {
  const fields:Field[]=[{key:'date',label:'作业日期',type:'date',required:true},{key:'subject',label:'科目',type:'select',required:true,options:subjectOptions},{key:'type',label:'作业类型',type:'select',required:true,options:[{value:'WRITTEN',label:'书面作业'},{value:'ORAL',label:'口头作业'}]},{key:'title',label:'作业标题',required:true},{key:'description',label:'作业说明',type:'textarea'},{key:'studentIds',label:'布置给学生',type:'multi',required:true,options:studentOptions(students.data.value||[])},{key:'attachmentIds',label:'作业附件',type:'file',hint:'支持图片、音频、视频，单个文件不超过 20MB。'}]
  if(await openDialog({title:'布置学习作业',description:'为选定学生建立独立作业记录，便于逐一跟进与反馈。',fields,initial:{date:selectedDate.value,subject:'语文',type:'WRITTEN'},submit:v=>post('/homework/tasks',v),success:'作业已成功布置'}))refresh()
}
async function review(item:Homework) {
  if(await openDialog({title:`批阅作业 · ${item.studentName}`,description:item.title,fields:[{key:'status',label:'批阅结论',type:'select',required:true,options:[{value:'COMPLETED',label:'完成作业'},{value:'CORRECTION',label:'需要订正'}]},{key:'accuracy',label:'正确率（%）',type:'number',min:0,max:100,required:true},{key:'comment',label:'老师评语',type:'textarea',required:true}],initial:{status:'COMPLETED',accuracy:item.accuracy??100,comment:item.comment||''},submit:v=>post(`/homework/${item.id}/review`,v),success:'批阅结果已保存'})){detail.value=null;refresh()}
}
async function updateStatus(item:Homework,next:string) {
  const fields:Field[]=next==='PENDING_RECHECK'?[{key:'submissionText',label:'本次订正说明',type:'textarea',required:true},{key:'attachmentIds',label:'新的订正附件（可选）',type:'file'}]:next==='PENDING_REVIEW'?[{key:'submissionText',label:'完成情况',type:'textarea'},{key:'attachmentIds',label:'本次作业附件',type:'file',required:isParent.value&&item.type==='ORAL',hint:item.type==='ORAL'?'口头作业请上传录音。':''}]:[]
  if(await openDialog({title:`${label(next)} · ${item.studentName}`,description:`将「${item.title}」更新为${label(next)}，提交后等待老师检查。`,fields,confirm:'确认提交',submit:v=>post(`/homework/${item.id}/status`,{...v,status:next}),success:'作业状态已更新'})){detail.value=null;refresh()}
}
async function attachments(item:Homework) {
  if(await openDialog({title:`补充作业附件 · ${item.studentName}`,fields:[{key:'fileIds',label:'上传附件',type:'file',required:true,hint:'支持图片、音频、视频，单个文件不超过 20MB。'}],submit:v=>post(`/homework/${item.id}/attachments`,v),success:'附件已关联作业'})){detail.value=null;refresh()}
}
</script>
<template><PageHeader title="作业管理" subtitle="从认真书写，到及时反馈，让学习形成温暖的闭环。"><button v-if="!isParent" class="btn primary" @click="create"><AppIcon name="Plus" :size="17" />布置作业</button></PageHeader><section class="panel"><div class="filter-bar"><SoftSelect v-model="studentId" aria-label="作业学生" :options="[{value:'',label:'全部学生'}, ...(students.data.value || []).map(s => ({value:s.id,label:s.name}))]" /><SoftSelect v-model="subject" aria-label="作业科目" :options="[{value:'',label:'全部科目'}, ...subjectOptions]" /><SoftSelect v-model="status" aria-label="作业状态" :options="[{value:'',label:'全部状态'}, ...statuses.map(s => ({value:s,label:label(s)}))]" /><span class="filter-count">{{ selectedDate }} · {{ data?.length||0 }} 份作业</span><button class="icon-btn" aria-label="刷新作业" @click="refresh"><AppIcon name="RefreshCw" :size="17" /></button></div><LoadState :loading="loading" :error="error" :empty="!data?.length" title="今天的作业还在准备中" description="选择其他日期查看，或为学生布置新作业。" @retry="refresh"><div class="table-wrap"><table><thead><tr><th>学生 / 班级</th><th>作业内容</th><th>科目 / 类型</th><th>进度状态</th><th>正确率</th><th>操作</th></tr></thead><tbody><tr v-for="(item,index) in data" :key="item.id"><td><div class="person"><span class="student-avatar" :class="`avatar-${index%4}`">{{ item.studentName.slice(-2) }}</span><span><strong>{{ item.studentName }}</strong><small>{{ item.campusName }} · {{ item.className }}</small></span></div></td><td><button class="table-title" @click="detail=item">{{ item.title }}</button><small class="block muted truncate">{{ item.description || '暂无补充说明' }}</small></td><td><span class="subject-tag">{{ item.subject }}</span><small class="block muted">{{ label(item.type) }}</small></td><td><StatusBadge :value="item.status" /></td><td class="numeric">{{ item.accuracy==null?'—':`${item.accuracy}%` }}</td><td><div class="row-actions"><button class="text-btn" @click="detail=item">详情</button><button v-if="!isParent" class="text-btn" @click="review(item)">批阅</button><button v-if="!isParent&&item.status==='NOT_STARTED'" class="text-btn" @click="updateStatus(item,'IN_PROGRESS')">开始</button><button v-if="isParent&&['NOT_STARTED','IN_PROGRESS'].includes(item.status)" class="text-btn" @click="updateStatus(item,'PENDING_REVIEW')">提交</button><button v-if="item.status==='CORRECTION'" class="text-btn" @click="updateStatus(item,'PENDING_RECHECK')">提交订正</button></div></td></tr></tbody></table></div></LoadState></section><Teleport to="body"><div v-if="detail" class="modal-overlay" @mousedown.self="detail=null"><section class="modal detail-modal" role="dialog" aria-modal="true" aria-labelledby="homework-title"><header class="modal-header"><div><span class="eyebrow">{{ detail.studentName }} · {{ detail.date }} · {{ detail.subject }}</span><h2 id="homework-title">{{ detail.title }}</h2></div><button class="icon-btn" aria-label="关闭作业详情" @click="detail=null"><AppIcon name="X" /></button></header><div class="detail-body"><StatusBadge :value="detail.status" /><p class="prose">{{ detail.description || '暂无作业说明' }}</p><AttachmentList :files="detail.attachments" /><div class="quote-card"><span class="eyebrow">老师评语 · 正确率 {{ detail.accuracy??'—' }}%</span><p>{{ detail.comment||'等待老师用心反馈' }}</p></div><div class="detail-links"><button class="btn secondary" @click="attachments(detail)"><AppIcon name="Paperclip" :size="16" />添加附件</button><button v-if="!isParent" class="btn primary" @click="review(detail)">批阅作业</button><button v-if="!isParent&&['NOT_STARTED','IN_PROGRESS'].includes(detail.status)" class="btn secondary" @click="updateStatus(detail,'PENDING_REVIEW')">送交批阅</button><RouterLink v-if="!isParent" :to="`/mistakes?studentId=${detail.studentId}&homeworkId=${detail.id}`" class="btn secondary" @click="detail=null">记录错题</RouterLink></div></div></section></div></Teleport></template>
